/**
 * SIP//LAB — 2-Minute Step-in-Place Biomechanics Lab — Configuration
 *
 * Single source of truth for every tunable parameter. Documented in
 * DATA_DICTIONARY.md (generated by tools/dictionary.html). Items marked
 * [TUNE] are engineering defaults that have NOT been validated against a
 * criterion measure (see pilot protocol F6) and may change after validation.
 *
 * View is FRONTAL: the participant faces the phone (confirmed 18 Oct 2026).
 * The scored criterion is knee height relative to hip height — a vertical
 * quantity preserved from the front.
 *
 * No build step. Loaded via a classic <script> tag; exposes global `CONFIG`.
 */
const CONFIG = {
    app: {
        name: 'Step-in-Place Biomechanics Lab',
        version: '1.0.0',
        analysisVersion: '1.0.0',
        schemaVersion: '1.0'
    },

    // Google Sheets (Apps Script web app). Leave empty to disable upload
    // (local ZIP export always works). Paste the /exec URL here after deploy.
    sheets: {
        webhookUrl: '',
        uploadFrames: false,   // true = also upload the 30 Hz analysed series to a "Frames" sheet
        framesChunkRows: 500   // batch size when uploading frames
    },

    // MediaPipe Pose Landmarker — pinned versions copied from the STS app.
    pose: {
        defaultModel: 'full',
        numPoses: 1,
        detectionConfidence: 0.5,
        presenceConfidence: 0.5,
        trackingConfidence: 0.5,
        bundleUrl: 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.18/vision_bundle.mjs',
        wasmUrl: 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.18/wasm',
        models: {
            lite:  'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task',
            full:  'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/1/pose_landmarker_full.task',
            heavy: 'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_heavy/float16/1/pose_landmarker_heavy.task'
        }
    },

    // Test protocol: 2-Minute Step in Place (Senior Fitness Test; Rikli & Jones).
    protocol: {
        durationS: 120,         // scored test window
        countdownS: 3,          // 3-2-1 before GO
        preRollS: 1.0,          // frames kept before GO (filter warm-up)
        tailS: 2.0,             // frames kept after 120 s (let the last lift finish)
        view: 'front',          // RESOLVED: frontal (participant faces the phone)
        cameraDistanceM: [2.5, 3.0],
        cameraHeightM: [0.9, 1.1]
    },

    // Camera / frontal-setup gates (S2). See brief B2a.
    camera: {
        maxPitchDeg: 5,             // [TUNE] device pitch/roll tolerance from upright
        hipYNormRange: [0.35, 0.65],// [TUNE] acceptable median hip-mid y (video-native normalised)
        minFrontalness: 0.8,        // [TUNE] shoulder_width / trunk_length to count as "facing camera"
        spanRange: [0.65, 0.90],    // head-to-ankle span as fraction of frame height
        defaultFacing: 'environment'// rear camera default (operator-assisted); 'user' = front/selfie
    },

    // Signal processing (offline authoritative pass).
    signal: {
        resampleHz: 30,
        cutoffHz: 8,            // [TUNE] effective -3 dB cutoff of the zero-lag Butterworth
        maxGapS: 0.25,          // gaps longer than this are flagged (still bridged for filtering)
        minVisibility: 0.5,     // MediaPipe visibility below this = marker treated as missing
        padSamples: 30          // reflection padding samples for filtfilt
    },

    // Knee-lift event detection on progress p(t): 0 standing, 1 knee at hip level.
    events: {
        countP: 0.85,           // [TUNE] default "a little at hip level" counts
        countPOfficial: 0.50,   // "official midpoint" preset (patella-iliac-crest midpoint)
        releaseP: 0.55,         // [TUNE] hysteresis: must fall below this before next count
        lowP: 0.15,             // onset/offset timing level
        minSameLegS: 0.25,      // minimum same-leg inter-step time
        bothKneesMaxS: 0.2,     // both knees >= countP longer than this => BOTH_KNEES_UP
        minProminence: 0.2,     // [TUNE] min peak prominence for offline local-maxima detection
        maxP: 2.0,              // p above this is an artefact and discarded
        hipRef: 'same_side',    // 'same_side' | 'mid' (hip midpoint; use if pelvic hiking dominates)
        gapPeakPolicy: 'flag'   // 'flag' = count across a low-visibility apex but flag the step
    },

    // Rest detection.
    rest: {
        restGapS: 3             // [TUNE] no counted step by either leg for longer than this = a rest
    },

    // Calibration (stand-still hold).
    calibration: {
        holdS: 2.0,
        maxJitterTrunkFrac: 0.04,   // [TUNE] max SD of hip-mid/ankle during hold, trunk fraction
        heightRangeCm: [120, 210],
        fallbackWindowS: 10         // if calibration skipped: median of lowest-knee frames in first 10 s
    },

    // Whole-body anthropometry (Winter, 2009): shoulder->hip->knee->ankle chain = 0.779 H.
    anthropometry: { segmentChainFractionOfHeight: 0.779 },

    // Quality control thresholds.
    qc: {
        minEffectiveFps: 15,
        minValidFramePct: 90,
        maxImputedPct: 10,
        maxGapS: 0.5,
        maxFeetOutPct: 5,
        maxShoulderWidthChangePct: 25,  // OBLIQUE_VIEW (non-blocking)
        maxHeightDiffPct: 15,           // scale-derived height vs entered
        maxBothKneesUpPct: 5,
        maxLift2d3dDiff: 0.25,
        longRestPct: 20,
        // Blocking flags withhold norm classification.
        blocking: ['LOW_FPS', 'LOW_VALID_FRAMES', 'TRACKING_GAPS', 'FEET_OUT_OF_FRAME',
                   'CAMERA_OR_FEET_SHIFT', 'MANUAL_STOP', 'TAB_HIDDEN', 'NO_STEPS',
                   'CAL_NOT_STILL', 'HEIGHT_IMPLAUSIBLE', 'BOTH_KNEES_UP']
    },

    // Live (causal) counter during the test; the offline analysis is authoritative.
    live: { emaAlpha: 0.4 },

    // MediaPipe landmarks recorded (index in the 33-point model). Order defines array layout.
    // 1 + 17x7 raw columns = t_ms + per-marker [x,y,z,v,wx,wy,wz].
    tracked: [
        { idx: 0,  key: 'nose',   name: 'nose',             role: 'Frame-fit (head in frame), facing check.' },
        { idx: 11, key: 'l_sh',   name: 'left_shoulder',    role: 'Scale chain, trunk lean, shoulder tilt, frontalness (rotation) check.' },
        { idx: 12, key: 'r_sh',   name: 'right_shoulder',   role: 'Scale chain, trunk lean, shoulder tilt, frontalness (rotation) check.' },
        { idx: 13, key: 'l_el',   name: 'left_elbow',       role: 'Recorded only.' },
        { idx: 14, key: 'r_el',   name: 'right_elbow',      role: 'Recorded only.' },
        { idx: 15, key: 'l_wr',   name: 'left_wrist',       role: 'Recorded only (support use is not penalised).' },
        { idx: 16, key: 'r_wr',   name: 'right_wrist',      role: 'Recorded only (support use is not penalised).' },
        { idx: 23, key: 'l_hip',  name: 'left_hip',         role: 'Same-side lift reference, pelvis tilt, sway, hip-height camera check, scale chain.' },
        { idx: 24, key: 'r_hip',  name: 'right_hip',        role: 'Same-side lift reference, pelvis tilt, sway, hip-height camera check, scale chain.' },
        { idx: 25, key: 'l_kn',   name: 'left_knee',        role: 'PRIMARY lift signal (left).' },
        { idx: 26, key: 'r_kn',   name: 'right_knee',       role: 'PRIMARY lift signal (right = official score).' },
        { idx: 27, key: 'l_an',   name: 'left_ankle',       role: 'Scale chain, feet-in-frame, camera/feet-shift check.' },
        { idx: 28, key: 'r_an',   name: 'right_ankle',      role: 'Scale chain, feet-in-frame, camera/feet-shift check.' },
        { idx: 29, key: 'l_heel', name: 'left_heel',        role: 'Feet-in-frame, ground reference (exploratory).' },
        { idx: 30, key: 'r_heel', name: 'right_heel',       role: 'Feet-in-frame, ground reference (exploratory).' },
        { idx: 31, key: 'l_toe',  name: 'left_foot_index',  role: 'Feet-in-frame, ground reference (exploratory).' },
        { idx: 32, key: 'r_toe',  name: 'right_foot_index', role: 'Feet-in-frame, ground reference (exploratory).' }
    ],

    // Rikli & Jones (2002) 2-Minute Step norms via Topend Sports.
    // Each row: [ageLow, ageHigh, belowBelowThreshold, aboveThreshold]
    //   below average  = steps <  belowThreshold
    //   average        = belowThreshold <= steps <= aboveThreshold
    //   above average  = steps >  aboveThreshold
    // NOTE: the published source lists 65-69 men average as "86 to 116" while
    // below-average is "< 87"; we keep the published values as-is.
    norms: {
        reference: 'Rikli & Jones (2002) 2-Minute Step in Place, via Topend Sports',
        ageRange: [60, 94],
        male: [
            [60, 64, 87, 115],
            [65, 69, 87, 116],
            [70, 74, 80, 110],
            [75, 79, 73, 109],
            [80, 84, 71, 103],
            [85, 89, 59, 91],
            [90, 94, 52, 86]
        ],
        female: [
            [60, 64, 75, 107],
            [65, 69, 73, 107],
            [70, 74, 68, 101],
            [75, 79, 68, 100],
            [80, 84, 60, 91],
            [85, 89, 55, 85],
            [90, 94, 44, 72]
        ]
    },

    sounds: { enabled: true }
};

if (typeof module !== 'undefined') module.exports = CONFIG;
